import { Contract, GlobalState, LocalState, abimethod, uint64, Txn, Global, Uint64, assert, Account, itxn, clone } from '@algorandfoundation/algorand-typescript'

export class JokePayPerCall extends Contract {
  // Service configuration
  owner = GlobalState<Account>({ key: 'o' })
  pricePerCall = GlobalState<uint64>({ key: 'p' }) // in microUSDC (5000 = 0.005 USDC)
  totalJokesServed = GlobalState<uint64>({ key: 'tc' })

  // User credit balance (prepaid)
  userBalance = LocalState<uint64>({ key: 'b' })

  public createApplication(): void {
    this.owner.value = Txn.sender
    this.pricePerCall.value = Uint64(5000)
    this.totalJokesServed.value = Uint64(0)
  }

  public optInToApplication(): void {
    this.userBalance(Txn.sender).value = Uint64(0)
  }

  @abimethod()
  public initialize(price: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can initialize')
    this.pricePerCall.value = price
  }

  /**
   * record_payment is called by the x402 facilitator or service owner 
   * after a USDC transfer has been verified on-chain.
   */
  @abimethod()
  public record_payment(sender: Account, amount: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner/facilitator can record')
    const currentBalance = this.userBalance(sender).value
    this.userBalance(sender).value = currentBalance + amount
  }

  /**
   * increment_usage is called by the API middleware when a joke is successfully served.
   * This deducts the price from the user's local balance.
   */
  @abimethod()
  public increment_usage(user: Account): void {
    assert(Txn.sender === this.owner.value, 'Only owner can increment usage')
    const price = this.pricePerCall.value
    const balance = this.userBalance(user).value

    assert(balance >= price, 'Insufficient balance')

    this.userBalance(user).value = balance - price
    this.totalJokesServed.value = this.totalJokesServed.value + Uint64(1)
  }

  @abimethod({ readonly: true })
  public get_service_stats(): uint64 {
    return this.totalJokesServed.value
  }

  /**
   * Allows the owner to withdraw accumulated USDC from the contract account.
   * Note: This assumes the contract holds the USDC Asset.
   */
  @abimethod()
  public withdraw(asset: uint64, amount: uint64): void {
    assert(Txn.sender === this.owner.value, 'Only owner can withdraw')

    itxn.assetTransfer({
      xferAsset: asset,
      assetReceiver: this.owner.value,
      assetAmount: amount,
      fee: Uint64(0),
    }).submit()
  }
}

